//! Raw FFI bindings generated by bindgen from the xmlsec1/libxml2 headers,
//! plus thin aliases for the enum constants whose generated names are
//! unreadable (§7.2).
//!
//! Nothing in here is safe to call directly — every call site must uphold
//! libxmlsec1's own invariants (init-before-use, non-null docs/nodes,
//! matching create/destroy pairs, etc). [`crate::dsig`] is the only module
//! that calls into this one; everything *it* exposes is safe.

#![allow(
    non_upper_case_globals,
    non_camel_case_types,
    non_snake_case,
    dead_code,
    clippy::upper_case_acronyms
)]

include!(concat!(env!("OUT_DIR"), "/bindings.rs"));

// --- Readable aliases for bindgen's unreadable enum constant names ------

/// PEM key data format (`xmlSecKeyDataFormatPem`).
pub const KEY_FORMAT_PEM: xmlSecKeyDataFormat =
    xmlSecKeyDataFormat_xmlSecKeyDataFormatPem;

/// PEM certificate format (`xmlSecKeyDataFormatCertPem`).
pub const KEY_FORMAT_CERT_PEM: xmlSecKeyDataFormat =
    xmlSecKeyDataFormat_xmlSecKeyDataFormatCertPem;

/// Trusted key data type (`xmlSecKeyDataTypeTrusted`).
pub const KEY_DATA_TYPE_TRUSTED: xmlSecKeyDataType = xmlSecKeyDataTypeTrusted;

/// DSig verification succeeded.
pub const DSIG_STATUS_SUCCEEDED: xmlSecDSigStatus =
    xmlSecDSigStatus_xmlSecDSigStatusSucceeded;

/// DSig verification found an invalid signature.
pub const DSIG_STATUS_INVALID: xmlSecDSigStatus =
    xmlSecDSigStatus_xmlSecDSigStatusInvalid;

/// Same-document Reference URIs: empty `URI=""` and `URI="#id"`.
pub const URI_TYPE_EMPTY: xmlSecTransformUriType = xmlSecTransformUriTypeEmpty;
pub const URI_TYPE_SAME_DOCUMENT: xmlSecTransformUriType = xmlSecTransformUriTypeSameDocument;
